# Verified answer key: beginner background + why-correct + why-others-wrong + doc links.
# Dot-sourced by gh-600-build-quiz.ps1. All Learn-more URLs HEAD-checked (200).
$YNC = '<table class="yn"><tr><th>Statement</th><th>Answer</th></tr>{0}</table>'
function YN($rows) {
  ($rows | ForEach-Object { "<tr><td>$($_[0])</td><td class=`"ynv $($_.ToLower())`">$($_[1])</td></tr>" }) -join ''
}
function L($letter, $body) { "Correct answer: <b>$letter</b>$body" }
function BG($t) { "<div class=`"bg`"><b>New to this?</b> $t</div>" }
function WHY($t) { "<div class=`"why`">$t</div>" }
function WN($items) { "<span class=`"whead`">Why the others are wrong:</span><ul>" + (($items | ForEach-Object { "<li>$_</li>" }) -join '') + "</ul>" }
function SRC($links) {
  $f = @($links)
  $pairs = @()
  $i = 0
  while ($i -lt $f.Count) {
    if ($f[$i] -is [array]) { $pairs += ,@($f[$i][0], $f[$i][1]); $i++ }
    else { $pairs += ,@($f[$i], $f[$i + 1]); $i += 2 }
  }
  $out = ''
  foreach ($p in $pairs) {
    $out += "<li><a href=`"$($p[0])`" target=`"_blank`" rel=`"noopener`">$($p[1])</a></li>"
  }
  "<span class=`"whead`">Learn more:</span><ul class=`"learn`">$out</ul>"
}

