$A = @{
1 = "<img src=`"images/image3.png`" alt=`"official answer`">" + (BG "A custom agent (a <b>.agent.md</b> file) is a saved persona for Copilot: its <b>tools</b> list decides what it may do. <b>search</b> finds files and code, <b>read</b> opens and inspects them, <b>edit</b> changes files, <b>execute</b> runs shell commands, <b>agent</b> delegates to subagents, <b>web</b> browses the internet. A planning-only agent must look but never touch.") + (WHY "Box 1 = <b>search</b>, Box 2 = <b>read</b>: everything a plan needs, nothing it must not do.") + (WN @("<b>edit</b> would let the planner rewrite files.", "<b>execute</b> would let it run local commands.", "<b>agent</b> delegation is unnecessary for writing a plan.", "<b>web</b> is redundant: Microsoft Learn access already comes from the listed microsoftdocs MCP tools.")) + (SRC @(@($U_AGENTS,'Custom agents in VS Code (tools, handoffs)'),@($U_MCPVS,'MCP servers in VS Code')))
2 = (L "D" ((BG "The Copilot app-modernization agent upgrades legacy apps in three stages. <b>assessment.md</b> is the analysis report (breaking changes), <b>plan.md</b> is the strategy, and <b>tasks.md</b> is the live dashboard where every step flips through start, execute, validate (build + test), complete.") + (WHY "To verify each step and test results, read the live dashboard: <b>tasks.md</b>.") + (WN @("<b>A assessment.md</b> is written before the upgrade: analysis only, no step status.", "<b>B plan.md</b> describes strategy; it never tracks execution.", "<b>C agent.md</b> is not a modernization artifact at all.")) + (SRC @(@($U_MODC,'App modernization: assessment, plan, tasks.md'),@($U_UPOV,'Copilot upgrade: how the stages work')))))
3 = "<img src=`"images/image5.png`" alt=`"official answer`">" + (BG "Every Actions workflow gets a <b>GITHUB_TOKEN</b> proving its identity. <b>permissions</b> blocks decide what that token may touch. <b>contents</b> covers repo files, <b>pull-requests</b> covers PR operations, <b>issues</b> covers issues. Least privilege = default read-only, grant write only where needed.") + (WHY "Top-level <b>contents: read</b> (read-only default) · job <b>contents: write</b> (only the writer job) · step <b>pull-requests: write</b> (explicit PR create/approve).") + (WN @("<b>permissions: read-all</b> is not the required default here, and read-only never grants write.", "<b>issues: write</b>: nothing in the workflow touches issues.", "<b>pull-requests: read</b> cannot create or approve PRs.")) + (SRC @(@($U_TOKEN,'GITHUB_TOKEN permissions')))
4 = "<img src=`"images/image7.png`" alt=`"official answer`">" + (BG "Reviewers cannot see inside an agent run, so GitHub is the system of record: <b>artifacts</b> (upload-artifact) persist files after a run, the <b>PR body + timeline</b> narrate progress on the PR itself, and <b>View session</b> streams the live log.") + (WHY "<b>upload-artifact + retention</b> = durable downloadable outputs · <b>PR body/timeline</b> = reviewable signals · <b>View session</b> = real time.") + (WN @("Assigning an issue starts work but records nothing.", "Approve-and-run is a manual gate, not tracking.", "Mentioning @copilot on a merged PR restarts the agent instead of tracking it.")) + (SRC @(@($U_ART,'Workflow artifacts'),@($U_CODAG,'Copilot coding agent')))
5 = "<img src=`"images/image9.png`" alt=`"official answer`">" + (BG "When you assign an issue to Copilot, it reacts and works: an <b>eyes reaction</b> means it accepted, <b>timeline updates</b> narrate the run, and if <b>Actions checks sit idle</b>, the repo likely requires manual workflow approval (common for agent PRs).") + (WHY "Eyes = <b>acknowledged, PR coming</b> · timeline started = <b>actively running</b> · checks idle = <b>human must approve and run workflows</b>.") + (SRC @(@($U_CODAG,'Copilot coding agent')))
6 = (L "C" ((BG "The Copilot CLI supports <b>hooks</b>: small shell scripts fired on lifecycle events. <b>postToolUse</b> runs after each tool call, <b>sessionEnd</b> at session end, <b>errorOccurred</b> when an execution fails.") + (WHY "A command on every agent failure needs the failure event: <b>errorOccurred</b>.") + (WN @("<b>postToolUse</b> fires after every tool call, failures or not.", "<b>sessionEnd</b> fires once at the end regardless of outcome.", "<b>agentStop</b> is about the agent stopping, not about an execution error.")) + (SRC @(@($U_CLI,'Copilot CLI')))))
7 = (L "C" ((BG "<b>Plan mode</b> is a CLI working style: Copilot investigates, writes up its proposed approach, and waits for your approval before changing a single file. Flags like <b>--allow-all</b> do the opposite (skip all approvals); <b>/compact</b> only shrinks conversation context.") + (WHY "Review-then-agree before any change = <b>plan mode</b>.") + (WN @("<b>A --agent=Task</b> only picks an agent; it adds no approval gate.", "<b>B --allow-all</b> removes approvals entirely.", "<b>D /compact</b> manages context size; it produces no approvable plan.")) + (SRC @(@($U_CLI,'Copilot CLI')))))
8 = (L "C" ((BG "The coding agent plans from the issue text: a one-liner with no scope, no expected changes and no acceptance criteria leaves it guessing, so the PR comes back thin. Rich issue context is the cheapest quality lever.") + (WHY "The one-liner hid scope and expected changes, so the agent planned from almost nothing. A <b>clear problem description</b> repairs the actual input the agent reasons from.") + (WN @("<b>A memory</b> personalizes style; it cannot invent missing scope.", "<b>B MCP rate limits</b> throttle doc retrieval; unrelated to PR scope.", "<b>D setup-steps resources</b> fix the runner environment, not issue quality.")) + (SRC @(@($U_CODAG,'Copilot coding agent')))))
9 = (L "A" ((BG "Agent1 profile line 05 pins <b>tools: [read,search,edit]</b>. In agent profiles, omitting the tools key restores the default: everything available. MCP1, meanwhile, is wired through the repository MCP configuration (planned change 3), not the agent profile.") + (WHY "<b>Delete line 05</b>: the restriction itself is what blocks full tool access.") + (WN @("<b>B</b> prose in copilot-instructions.md also leaks into Chat and review (forbidden by change 2), and prose grants no tool access.", "<b>C</b> prose inside the profile likewise grants nothing.", "<b>D mcp-servers</b> belongs in the repo MCP config per the planned change, not the agent profile.", "<b>E tools: []</b> is an empty allow-list: the exact opposite of all-access.")) + (SRC @(@($U_AGENTS,'Custom agents in VS Code (tools, handoffs)'),@($U_MCPVS,'MCP servers in VS Code')))))
10 = (L "B" ((BG "The coding agent cannot see normal Actions secrets, and anything committed to git is visible to every reader. MCP credentials therefore live as <b>COPILOT_MCP_-prefixed secrets in the Copilot environment</b>, referenced by variable name from the MCP config.") + (WHY "<b>COPILOT_MCP_ secret + mcp.json reference</b>: the only channel the agent MCP runtime reads.") + (WN @("<b>A Codespaces secret</b> serves Codespaces, not the coding agent.", "<b>C plaintext apiKey in the repo</b> leaks the key to all readers.", "<b>D Actions secret + `${{ secrets }}`</b> never reaches the agent MCP runtime.")) + (SRC @(@($U_MCPVS,'MCP servers in VS Code'),@($U_CODAG,'Copilot coding agent')))))
11 = ($YNC -f (YN @(("Once MCP1 is configured, agent1 can invoke MCP1 tools autonomously.","Yes"),("agent1 can use the MCP resources and MCP prompts exposed by MCP1.","No"),("If new tools are added to MCP1, they will be available automatically to agent1.","Yes")))) + (BG "An <b>MCP server</b> plugs external capabilities into the agent. MCP defines three surfaces: <b>tools</b> (callable functions), <b>resources</b> (readable data) and <b>prompts</b> (templates). The coding agent consumes configured tools; a remote server re-advertises its tool list every session.") + (WHY "Configured tools are autonomously callable and refresh dynamically; but MCP1 was configured <b>as a tool</b>, so resources/prompts are not on the table here.") + (BG "<b>Example:</b> MCP1 exposes a <b>create_ticket</b> tool, so agent1 can file tickets by itself. If Litware adds a <b>close_ticket</b> tool next week, it simply shows up. But the agent cannot open a ticket attachment (a resource) or fill in a ticket template (a prompt).") + (SRC @(@($U_MCPVS,'MCP servers in VS Code'),@($U_AGENTS,'Custom agents in VS Code')))
12 = (L "C" ((BG "VS Code Copilot Chat discovers MCP servers from <b>mcp.json</b>. A workspace-level <b>.vscode/mcp.json</b> can be committed to git, so one file configures every developer and every agent centrally. Per-user settings and per-agent profiles cannot do that.") + (WHY "<b>.vscode/mcp.json</b>: committable, central, repo-wide.") + (WN @("<b>A .agent.md files</b> are per-agent personas, not MCP transport config.", "<b>B settings.json</b> is per-user local state: the opposite of central.", "<b>D &lt;project&gt;/.mcp/server.json</b> is project-scoped coding-agent config, not repo-wide Chat config.")) + (SRC @(@($U_MCPVS,'MCP servers in VS Code')))))
13 = (L "D" ((BG "LLM CLIs work inside a fixed <b>context window</b>. Long agentic sessions fill it. <b>/compact</b> summarizes the conversation so far into a short brief and keeps going; /context only shows scope, /yolo only controls approvals.") + (WHY "<b>/compact</b>: same work, smaller context, nothing lost.") + (WN @("<b>A /context</b> views scope; it frees nothing.", "<b>B /yolo</b> auto-approves tools; unrelated to context pressure.", "<b>C /clear</b> discards history instead of preserving it as a summary.")) + (SRC @(@($U_CLI,'Copilot CLI')))))
14 = (L "C" ((BG "Two GitHub mechanisms combine here. A <b>branch protection rule</b> can require pull-request reviews before merge on chosen paths; a <b>CODEOWNERS</b> file names who must review which paths. Together: designated reviewers must approve workflow/infra changes.") + (WHY "<b>Protection rule + CODEOWNERS</b>: gate plus designated approvers.") + (WN @("<b>A agents.md</b> is not an enforcement file.", "<b>B .copilotignore</b> only hides files from Copilot; it enforces no approval.", "<b>D copilot-instructions.md</b> guides agent behavior but cannot force human approval.")) + (SRC @(@($U_PROT,'Branch protection rules'),@($U_OWNERS,'CODEOWNERS')))))
15 = ($YNC -f (YN @(("The command will prevent runaway loops.","Yes"),("The command will allow the agent to use all tools.","Yes"),("The command will allow targeted human intervention at key decision points.","No")))) + (BG "This unattended script runs <b>copilot --autopilot --yolo --max-autopilot-continues 10</b>. <b>autopilot</b> = keep working without asking, <b>--yolo</b> = pre-approve every tool, <b>max-autopilot-continues</b> = hard cap on iterations.") + (WHY "The cap kills runaway loops; yolo unlocks every tool; but fully-automatic plus fully-approved leaves zero points where a human could step in.") + (BG "<b>Example:</b> without the cap, a dependency updater that always finds one more outdated package could loop forever; <b>--max-autopilot-continues 10</b> forces it to stop and report after 10 rounds.") + (SRC @(@($U_CLI,'Copilot CLI')))
16 = "Branch protection (main): <b>Enabled</b><br>Validation trigger: <b>on: pull_request</b>" + (BG "Trunk-based development = all work lands on main via short-lived PRs. The agent must be free to branch and open PRs, but main itself only moves through reviewed, CI-validated merges.") + (WHY "<b>Enabled</b> bans direct pushes and demands PR + approval; <b>on: pull_request</b> validates every agent PR before merge.") + (WN @("<b>Disabled</b> or <b>bypass for direct pushes</b> re-opens unreviewed pushes.", "<b>on: push</b> fires on direct pushes and misses PR gating.", "<b>on: schedule / workflow_dispatch</b> are not PR-driven, so validation would not gate merges.")) + (SRC @(@($U_PROT,'Branch protection rules')))
17 = (L "C" ((BG "The CLI exposes slash commands for session chores: <b>/usage</b> prints token consumption, /compact shrinks context, /diff shows pending changes, /context shows what the model can see.") + (WHY "Token usage readout = <b>/usage</b>.") + (WN @("<b>A /compact</b> manages context, <b>B /diff</b> shows changes, <b>D /context</b> shows scope: none reports tokens.")) + (SRC @(@($U_CLI,'Copilot CLI')))))
18 = "type: <b>http</b><br>Authorization: <b>Bearer `${env:GITHUB_PAT}</b>" + (BG "An MCP client config names each server with a transport <b>type</b> (http for a hosted HTTPS endpoint, stdio for a local process) plus auth headers. GitHub personal access tokens authenticate with the <b>Bearer</b> scheme.") + (WHY "<b>http</b> matches the hosted endpoint; <b>Bearer</b> matches PAT auth.") + (WN @("<b>stdio / local</b> describe process-local servers, not api.githubcopilot.com.", "<b>Token / x-api-key / Digest</b> are not the GitHub PAT scheme.")) + (SRC @(@($U_MCPVS,'MCP servers in VS Code')))
19 = (L "D" ((BG "<b>--allow-tool</b> pre-approves named tools (no more prompts for them); <b>--deny-tool</b> removes tools entirely. Unlisted tools stay usable but keep prompting. Read and search are low-risk; edit and execute are high-risk.") + (WHY "<b>--allow-tool 'read,search'</b>: fast reads, while edit/execute remain available behind explicit approval.") + (WN @("<b>A deny-only</b> still prompts for reads: no velocity gain.", "<b>B --allow-all-tools</b> also pre-approves edit/execute: unsafe.", "<b>C plain</b> prompts for everything: slow.", "<b>E + --deny</b> deletes edit/execute access, violating remain-available.")) + (SRC @(@($U_CLI,'Copilot CLI')))))
20 = "Run tests: <b>npm test</b><br>Prepare CodeQL: <b>init</b><br>Run CodeQL: <b>analyze</b>" + (BG "This repo tests with npm, and GitHub code scanning runs CodeQL as a fixed two-step action pair: <b>init</b> prepares the database, <b>analyze</b> runs the queries. upload-sarif exists only for third-party scanners.") + (WHY "npm runs this repo suite; init then analyze is the only valid CodeQL sequence.") + (WN @("<b>build</b> compiles instead of testing.", "<b>python -m unittest</b> is the wrong ecosystem.", "<b>upload-sarif</b> belongs to third-party SARIF uploads, not the native CodeQL flow.")) + (SRC @(@($U_SCAN,'Code scanning / CodeQL')))
21 = (L "A" ((BG "After the coding agent opens a PR, reviewers iterate by commenting. For the comment to reach the <b>same agent session</b>, the reviewer must be able to act on the repo (<b>write access</b>) and must ping the agent handle (<b>@copilot</b>) inside the <b>PR comments</b>. Anything else starts or targets the wrong session.") + (WHY "<b>Write access + @copilot in PR comments</b>: routable, same-session iteration.") + (WN @("<b>B</b>: agent-side access is not the gap; @github in task comments targets the wrong place.", "<b>C</b> unassign/reassign spawns a new session and drops iteration context.", "<b>D</b> a fresh Chat task is disconnected from the PR session.")) + (SRC @(@($U_CODAG,'Copilot coding agent')))))
22 = ($YNC -f (YN @(("The planner config explicitly prevents code changes in the same conversation.","Yes"),("The planner violates its tools via internet access; removing search fixes it.","No"),("Repo-level copilot-instructions requiring tests+linters mitigates failing-CI stalls.","Yes")))) + (BG "The planner allows only search/read/fetch plus written orders never to write code: that <b>is</b> explicit prevention (the observed edits are non-compliance, not config). Web fetching via the allowed <b>fetch</b> tool is legitimate, so network blocks are a firewall problem, while failing CI is a test-discipline problem.") + (WHY "Config forbids edits (Yes) · fetch is allowed so search-removal fixes nothing (No) · test/linter gates attack failing CI directly (Yes).") + (BG "<b>Example:</b> the planner with only search/read/fetch is like a chef with no stove: it can write the recipe (plan) but physically cannot cook (edit). The handoff button then moves you to the implementer agent, which does have a stove.") + (SRC @(@($U_AGENTS,'Custom agents in VS Code'),@($U_INSTR,'Custom instructions')))
23 = (L "D" ((BG "CLI <b>hooks</b> under .github/hooks/*.json intercept tool use. <b>preToolUse</b> runs before the command and can veto it with permissionDecision deny; userPromptSubmitted only observes prompts and sessionStart only runs once at launch.") + (WHY "<b>preToolUse + deny</b>: auto-allow the safe, block sudo / rm -rf / / curl-pipe-bash.") + (WN @("<b>A userPromptSubmitted</b> with nonzero exit breaks the session instead of gating one command.", "<b>B gitignore</b> hides logs; it enforces nothing.", "<b>C sessionStart banner</b> is cosmetic text with no blocking power.")) + (SRC @(@($U_CLI,'Copilot CLI')))))
24 = ($YNC -f (YN @(("On main, the agent appears as release-notes.","Yes"),("On branch2, the workspace release-notes agent is available.","No"),("profile1 agent (user-invokable: false) appears and overrides the workspace agent.","No")))) + (BG "VS Code discovers workspace agents from the <b>checked-out branch</b> (.github/agents/*.agent.md) and profile agents from your user profile. <b>user-invokable: false</b> hides a profile agent from the dropdown entirely.") + (WHY "Present on main (Yes) · absent on branch2 (No) · hidden profile agent overrides nothing (No).") + (BG "<b>Example:</b> on main the Chat agent picker lists <b>release-notes</b>; check out branch2 (file absent) and it vanishes; a profile agent with user-invokable:false never appears in any picker.") + (SRC @(@($U_AGENTS,'Custom agents in VS Code')))
25 = "Checkout ref: <b>`${{ inputs.ref }}</b><br>Profile path: <b>.github/agents/rollout-bot.md</b><br>Deploy arg: <b>inputs.ref</b>" + (BG "Rollback-by-revert works only if the workflow deploys <b>exactly the ref you name</b> (workflow_dispatch input) and reads the agent profile from the repo <b>at that same ref</b>. Workspace agent profiles conventionally live under .github/agents/.") + (WHY "inputs.ref pins the commit end-to-end; the profile path follows the workspace convention.") + (WN @("<b>github.ref</b> resolves to the workflow own ref, not your chosen deploy ref.", "<b>agents/rollout-bot.md</b> is the wrong directory.")) + (SRC @(@($U_AGENTS,'Custom agents in VS Code')))
26 = (L "A, D" ((BG "<b>Copilot Memory</b> stores repo facts (conventions, build commands) and personal preferences. Two documented lifecycle rules: owners/admins can <b>manually delete</b> repo facts, and any entry <b>unused for 28 days is auto-deleted</b> (use resets the timer).") + (WHY "<b>Manual deletion + 28-day expiry</b>: the two documented deletion paths.") + (WN @("<b>B archiving</b> deletes nothing by itself; inactive repos merely let entries expire via the 28-day rule.", "<b>C code deletion</b>: stale entries are ignored on validation, not auto-deleted.", "<b>E merging PRs</b> never deletes; closed-unmerged PRs can even create memories.")) + (SRC @(@($U_MEM,'Copilot Memory (concepts)')))))
27 = "Previous prompt irrelevant: <b>Start a new chat.</b><br>Stay focused in IDE: <b>Open related files and close unrelated files.</b>" + (BG "Copilot Chat builds context from <b>history + open files</b>. Old troubleshooting turns pollute answers; the cheapest reset is a fresh chat, and curating open files steers every future answer with zero configuration.") + (WHY "New chat = minimal-effort reset; working-set curation = continuous focus.") + (WN @("Deleting memories destroys useful repo knowledge.", "Deleting one request is fiddly and never fully resets context.", "Agent mode changes behavior instead of scoping context.", "Disabling all features is overkill for a context problem.")) + (SRC @(@($U_CODAG,'Copilot coding agent')))
28 = "Cross-device tools, no local setup: <b>GitHub-hosted MCP server</b>.<br>Org-wide tools everywhere: <b>Enable MCP servers in Copilot policy</b>." + (BG "Local MCP servers (Docker, /mcp add) exist only on one laptop, so github.com sessions lose them. A <b>GitHub-hosted MCP server</b> travels with the account, and the <b>org Copilot policy</b> switch turns servers on for every environment at once.") + (WHY "Hosted = zero-setup everywhere; policy = one central switch.") + (WN @("Docker/local MCP needs per-machine setup and is absent on github.com.", "/mcp add is per-device manual work.", "Changing mode does not unify tools.", "Disabling toolsets removes tools instead of unifying them.")) + (SRC @(@($U_MCPVS,'MCP servers in VS Code')))
29 = "Confirm progress: <b>View session from the pull request</b>.<br>Resume work: <b>post a PR comment mentioning @copilot</b>." + (BG "A 55-minute-silent agent may just be stuck, not dead. <b>View session</b> shows its live state, and an <b>@copilot PR comment</b> nudges the same session to continue: completed steps and approach survive.") + (WHY "Observe first, then continue in place: no redo, no approach change.") + (WN @("Repo insights / local git log show code, not agent progress.", "Close/reopen restarts and risks redoing work.", "Marking ready is premature.", "A new PR from Chat starts a new session.")) + (SRC @(@($U_CODAG,'Copilot coding agent')))
30 = (L "B" ((BG "The coding agent runs outside Actions, so Actions secrets are invisible to it, and anything in git is public to readers. Short-lived credentials for the agent belong in the <b>Copilot environment secrets</b>.") + (WHY "<b>Copilot environment secret</b>: the only secret store the agent runtime reads.") + (WN @("<b>A Actions secret</b> serves workflows, not the agent.", "<b>C instructions file / D agent config</b> commit the token in plaintext: a leak.")) + (SRC @(@($U_CODAG,'Copilot coding agent')))))
31 = (L "A" ((BG "Memories point at code (<b>citations</b>). Before each use, Copilot re-checks those citations against the current branch: moved or deleted code means the memory is skipped, so stale knowledge can never drive an answer.") + (WHY "<b>Validate-then-ignore-stale</b>: freshness is enforced at use time.") + (WN @("<b>B</b>: repository facts are shared with everyone having memory access, not locked to the creator.", "<b>C</b> contradicts the documented 28-day expiry of unused entries.", "<b>D</b> is backwards: closed-unmerged PRs can seed memories.")) + (SRC @(@($U_MEM,'Copilot Memory (concepts)')))))
32 = (L "B" ((BG "An empty-but-successful PR means the agent did work that produced no diff: only its own narration explains why. The <b>Agents panel session log</b> records reasoning, tool calls and decisions; runner logs show infra output and metrics show aggregates.") + (WHY "<b>Session log</b>: the sole artifact containing agent intent.") + (WN @("<b>A GITHUB_TOKEN perms</b> describe auth scope, not behavior.", "<b>C runner log</b> shows infrastructure, not decisions.", "<b>D usage metrics</b> aggregate many sessions.")) + (SRC @(@($U_CODAG,'Copilot coding agent')))))
33 = ($YNC -f (YN @(("The Github MCP server is enabled for the agent sessions.","Yes"),("Workspace isolation is being used by the agent sessions.","No"),("The logs show exactly two agent sessions started.","Yes")))) + (BG "Read the log literally: <b>Passing 1 MCP server(s) [github]</b> means the server reached the session (CLIMCPServerEnabled=false only gates extra CLI-side servers). <b>isolationEnabled: false</b> with no worktree means isolation never engaged. Sessions are the two distinct <b>isNewSession: true</b> IDs.") + (WHY "Server passed (Yes) · isolation off (No) · two session IDs (Yes).") + (BG "<b>Example lines:</b> <b>Passing 1 MCP server(s) to SDK: [github]</b> proves statement 1; <b>isolationEnabled: false</b> with no worktree disproves statement 2; two <b>Invoking... isNewSession: true</b> IDs (de04f0fe, 6852c5dc) prove statement 3.") + (SRC @(@($U_CLI,'Copilot CLI'),@($U_MCPVS,'MCP servers in VS Code')))
34 = ($YNC -f (YN @(("[Statement_2] The agent responded with messages.","No"),("[Statement_3] The agent can edit files in the repository.","No"),("[Statement_1] The agent analyzed files in the repository.","No")))) + (BG "This log contains only model calls and progress notes. <b>message 0 returned</b> literally means zero messages produced; <b>[panel/editAgent]</b> is a UI panel tag, not a file edit; and no line shows any file read, search or analysis.") + (WHY "No messages, no edits, no file analysis anywhere: all three No.") + (BG "<b>Example:</b> <b>message 0 returned</b> means the model call ended having produced zero messages: silence, not a reply. <b>[panel/editAgent]</b> names the VS Code side panel, not a file operation: zero evidence of repository edits.") + (SRC @(@($U_CODAG,'Copilot coding agent')))
35 = (L "D" ((BG "Copilot code review reads repo-wide guidance from <b>.github/copilot-instructions.md</b> (always applied), while <b>.github/instructions/*.instructions.md</b> files are path-scoped via applyTo, agent profiles scope single agents, and the PR template is human boilerplate.") + (WHY "<b>copilot-instructions.md</b>: the documented repo-wide home for review guidance.") + (WN @("<b>A PR template</b> instructs human authors, not the reviewer.", "<b>B .agent.md profiles</b> scope one agent, not all reviews.", "<b>C instructions/*.instructions.md</b> applies only to matching paths.")) + (SRC @(@($U_INSTR,'Custom instructions')))))
36 = (L "B" ((BG "The agent found a loophole: editing workflows silences failing checks. Blocking the loophole stops the symptom; <b>rewriting the repo instructions</b> (never touch workflows, fix the underlying code) cures the strategy.") + (WHY "<b>Update copilot-instructions.md</b>: teach the right goal, not just block the wrong one.") + (WN @("<b>A --allow-all</b> grants even more autonomy: worse.", "<b>C ruleset</b> blocks the bypass but the agent stalls instead of fixing code.", "<b>D disabling Actions</b> deletes validation entirely.")) + (SRC @(@($U_INSTR,'Custom instructions')))))
37 = (L "D" ((BG "GitHub records security-relevant actions as named <b>audit log events</b> with actor and timestamp. Artifact deletion is the <b>artifact.destroy</b> event: filter for it to answer who deleted what and when.") + (WHY "<b>artifact.destroy</b>: the exact event for this question.") + (WN @("<b>A checks.delete_logs</b> belongs to a different event family.", "<b>B PR text</b> and <b>C merge history</b> record discussion and commits, never artifact deletion.")) + (SRC @(@($U_STREAM,'Audit log streaming')))))
38 = (L "C" ((BG "A session that stopped (here: the 70-minute mark) will never finish on its own. The supported restart is <b>unassign + reassign the issue</b>: Copilot picks it up fresh from the same issue context. Commenting @copilot is for steering a live PR, not reviving a dead session.") + (WHY "<b>Unassign/reassign</b>: the documented session restart.") + (WN @("<b>A waiting</b> never resolves a stall.", "<b>B merging</b> an empty PR is wrong, and merged sessions are closed.", "<b>D Approve-and-run</b> gates workflows; it does not revive agents.")) + (SRC @(@($U_CODAG,'Copilot coding agent')))))
39 = (L "D" ((BG "GitHub keeps audit history briefly; there is no 2-year retention knob. Long-lived compliance history requires <b>streaming audit events out</b> to your own sink (Azure Event Hubs, S3, etc.) as they happen.") + (WHY "<b>Stream to Event Hubs</b>: the only path to multi-year immutable history.") + (WN @("<b>A retention setting</b> with a multi-year value does not exist.", "<b>B log forwarding</b> names no compliant sink.", "<b>C Git events toggle</b> selects event types, not retention.")) + (SRC @(@($U_STREAM,'Audit log streaming')))))
40 = (L "C" ((BG "A <b>preToolUse</b> hook inspects each tool call before it runs and can deny it; the denial surfaces right in the live stream. postToolUse only observes completed calls, app policies govern installs, and firewall blocks look like network failures.") + (WHY "Mid-stream failure during a tool call = hook denial.") + (WN @("<b>A postToolUse</b> runs after success; it cannot break a live call.", "<b>B app policy</b> governs installs/permissions, not runtime calls.", "<b>D firewall</b> produces network errors, a different shape.")) + (SRC @(@($U_CLI,'Copilot CLI')))))
41 = (L "C" ((BG "Classify by where it broke: the agent called the Microsoft Docs MCP search tool and the <b>invocation itself failed before any result</b>. That is <b>tool misuse</b>: not bad reasoning (logic error, call succeeds), not a context problem (prompt/window sizing), not a network outage (transport failure).") + (WHY "<b>Tool misuse</b>: failed invocation, no result.") + (WN @("<b>A context issue</b> would be sizing/scope of the prompt.", "<b>B reasoning error</b> means flawed logic with a working call.", "<b>D network issue</b> means the transport failed.")) + (SRC @(@($U_CODAG,'Copilot coding agent'),@($U_MCPVS,'MCP servers in VS Code')))))
42 = (L "B" ((BG "The <b>gh agent-task</b> extension manages agent tasks. <b>view</b> targets one task, <b>--log</b> prints its session log, <b>--follow</b> keeps streaming like tail -f. --jq only queries static JSON; list only enumerates; --web opens a browser.") + (WHY "<b>view --log --follow</b>: one task, live log.") + (WN @("<b>A --jq</b> queries a static snapshot: no streaming.", "<b>C/D list</b> enumerate tasks; --web opens a browser and --status filters: neither streams a log.")) + (SRC @(@($U_CODAG,'Copilot coding agent')))))
43 = (L "C, E" ((BG "The coding agent ships <b>built-in scanners</b> that judge generated code: <b>secret scanning</b> flags hardcoded keys/tokens, <b>CodeQL code scanning</b> flags vulnerabilities. Your CI lint, AI review prose and usage dashboards are useful but none is a built-in scanner signal.") + (WHY "<b>Secret detection + CodeQL</b>: the two scanner signals.") + (WN @("<b>A repo CI lint</b> is your pipeline, not built-in.", "<b>B review comments</b> are reviewer prose, not scanner output.", "<b>D time-to-merge</b> measures process, not this code.")) + (SRC @(@($U_SECRET,'Secret scanning'),@($U_SCAN,'Code scanning / CodeQL')))))
44 = (L "B" ((BG "Runners are ephemeral and jobs isolated: files pass between jobs only through <b>upload-artifact / download-artifact</b>. Caches are best-effort (for dependencies), commits pollute history, and network shares add infra runners cannot rely on.") + (WHY "<b>Upload in agent-run, download in review/deploy</b>: the native handoff.") + (WN @("<b>A caching</b> is best-effort dependency storage, not a file handoff.", "<b>C committing</b> generated files pollutes the repo.", "<b>D network share</b> is external infra with no availability guarantee.")) + (SRC @(@($U_ART,'Workflow artifacts')))))
45 = (L "A" ((BG "<b>Plan mode</b> exists so nothing happens except planning: Copilot investigates and writes the plan to <b>plan.md</b>, then stops. Branches, PRs and implementation are all actions beyond planning.") + (WHY "<b>saves the plan to plan.md</b>: planning-only, by definition.") + (WN @("<b>B branch / C PR / D implement</b> each contradict plan-mode semantics.")) + (SRC @(@($U_CLI,'Copilot CLI')))))
46 = (L "B" ((BG "Three constraints must hold at once: agents run <b>concurrently</b>, on <b>isolated branches</b>, with <b>file conflicts caught before merge</b>. Only separate branches plus a required overlap-detecting status check satisfies all three.") + (WHY "<b>Separate branches + overlap check</b>: parallel, concurrent, safe.") + (WN @("<b>A CODEOWNERS</b> adds review but no branch isolation: outputs still collide.", "<b>C read-only tools</b> makes the agents unable to do their jobs.", "<b>D concurrency group</b> serializes the workflows, violating concurrency.")) + (SRC @(@($U_CODAG,'Copilot coding agent'),@($U_PROT,'Branch protection rules')))))
47 = ($YNC -f (YN @(("The Run Review handoff resolves to review.agent.md.","No"),("The Start Implementation handoff fails to identify the target agent.","No"),("Selecting Start Implementation switches chat + auto-submits via GPT-5.2 (copilot).","Yes")))) + (BG "Per VS Code docs, <b>handoffs.agent is the target agent identifier = the file-name stem</b> (planner example uses agent: implementation). <b>send: true</b> auto-submits the prompt; <b>model</b> takes the qualified Model (vendor) form.") + (WHY "code-review matches no file stem (No) · implementer resolves (No to fails) · send:true + GPT-5.2 (copilot) auto-submits (Yes).") + (BG "<b>Example:</b> planner.agent.md has identifier <b>planner</b>. Handoff <b>agent: implementer</b> looks for implementer.agent.md (found, resolves). Handoff <b>agent: code-review</b> looks for code-review.agent.md (missing: review.agent.md does not count, identifiers match file stems, not frontmatter names).") + (SRC @(@($U_AGENTS,'Custom agents in VS Code (incl. handoffs)')))
48 = "Scope: <b>Set concurrency at the workflow level.</b><br>Expression: <b>group: `${{ github.workflow }}-`${{ github.ref }}</b>" + (BG "A <b>concurrency group</b> serializes runs sharing a key. Keyed per branch (<b>github.ref</b>), rapid pushes to one PR queue while different PRs run in parallel. The key must scope the <b>workflow</b>, and any key containing <b>run_id</b> (unique per run) groups nothing.") + (WHY "Workflow-level per-branch group: parallel across PRs, serialized per branch.") + (WN @("<b>Job-level only</b> scopes the wrong level: pushes still overlap.", "<b>strategy.matrix</b> limits parallelism; it never groups runs.", "<b>head_ref || run_id / run_id</b>: run_id is unique, so every run is its own group.")) + (SRC @(@($U_CONC,'Workflow concurrency groups')))
49 = (L "D" ((BG "An <b>Orchestrator</b> pattern delegates phases to subagents. Model-driven delegation reads the <b>agents array in the Orchestrator frontmatter</b>: only listed agents are callable. Handoffs drive chat buttons; the tools list holds tools, not agents.") + (WHY "<b>Add Summarizer to the Orchestrator agents list</b>: listing is what makes it callable.") + (WN @("<b>A/B Reviewer</b> is not the invoking agent.", "<b>C tools list</b>: subagents are agents, not tools.")) + (SRC @(@($U_AGENTS,'Custom agents in VS Code')))))
50 = (L "D" ((BG "The audit log is queried by field filters. Event-type filtering uses the <b>action:</b> qualifier, and artifact deletion is the <b>artifact.destroy</b> event.") + (WHY "<b>action:artifact.destroy</b>: exactly the deletion events.") + (WN @("<b>A repo:</b> filters by repository, not by event.", "<b>B action:workflows.run</b> matches run events, not deletions.", "<b>C operation:remove</b> is not a valid audit filter.")) + (SRC @(@($U_STREAM,'Audit log streaming')))))
51 = (L "A" ((BG "Three frontmatter flags, three meanings: <b>agents[]</b> = callable subagents, <b>user-invocable: false</b> = humans cannot @-mention it, <b>disable-model-invocation: true</b> = the model cannot call it. Explorer/Modifier run through the same agents array, so the array works: only Summarizer self-blocks.") + (WHY "<b>disable-model-invocation: true</b>: the one flag that bars model-driven calls.") + (WN @("<b>B handoffs</b> drive chat buttons, not agents-array calls: Explorer/Modifier prove handoffs unnecessary.", "<b>C user-invocable</b> gates humans, not the model.", "<b>D editing tools</b>: a summary needs only fetch.")) + (SRC @(@($U_AGENTS,'Custom agents in VS Code')))))
52 = "Fan-out/fan-in: <b>needs: [spec_analyzer, risk_reviewer]</b> on plan_merger<br>Concurrency at <b>workflow level</b>, group <b>multiagent-`${{ github.ref }}</b>" + (BG "<b>needs</b> builds the DAG: plan_merger waits until both parallel analyzers finish (fan-out then fan-in). <b>Workflow-level concurrency</b> keyed per ref keeps branches parallel while same-branch pushes serialize.") + (WHY "needs = wait for both; per-ref workflow group = parallel branches, serial pushes.") + (SRC @(@($U_CONC,'Workflow concurrency groups')))
53 = "tools: <b>[search,read,fetch]</b><br>handoff send: <b>false</b>" + (BG "Read-only means <b>no write power at all</b>: search, read and fetch only qualify, while edit/commit/push/merge/publish all write. And <b>send: false</b> (the default) keeps the handoff a button the human fires after approving the plan.") + (WHY "Read-only toolset + human-gated handoff.") + (WN @("Any list containing edit/commit/push/merge/publish grants write power.", "send:true would auto-submit the handoff before approval.")) + (SRC @(@($U_AGENTS,'Custom agents in VS Code (incl. handoffs)')))
54 = "1. <b>Add the plan job first</b> (uploads plan output as artifact)<br>2. <b>Create the plan-review environment with SG_Review as required reviewers</b><br>3. <b>Add the execute job with needs: [plan] and environment: plan-review</b>" + (BG "The security demands: <b>only SG_Review approves plan outputs</b>, execution waits for that approval. GitHub <b>environments</b> gate jobs behind named required reviewers; <b>needs</b> orders the jobs. Order is load-bearing: produce, gate, then execute.") + (WHY "Produce the plan, gate it behind SG_Review, then execute the approved plan.") + (WN @("Auto-advance on green skips the required approval.", "A 2-approval main-branch ruleset gates pushes, not plan outputs.", "SG_Dev as reviewers violates SG_Review-only approval.")) + (SRC @(@($U_ENV,'Environments + required reviewers'),@($U_CODAG,'Copilot coding agent')))
55 = (L "C" ((BG "The agent touched repos outside its scope because its <b>credential</b> allowed it. A <b>fine-grained PAT</b> can be limited to one repository: scoped to product-api, billing-service and infra-terraform become unreachable. Prose instructions are unenforceable, and rulesets only block pushes.") + (WHY "<b>Scoped PAT</b>: fix the scope at the credential layer.") + (WN @("<b>A prose instruction</b> (do not access X) is unenforced: agents can ignore it.", "<b>B permissions block</b> scopes GITHUB_TOKEN, not the agent session credential.", "<b>D bot-push ruleset</b> blocks only pushes by one identity: reads continue, and the agent may not even push as the bot.")) + (SRC @(@($U_PAT,'Fine-grained personal access tokens'),@($U_TOKEN,'GITHUB_TOKEN permissions')))))
56 = (L "A, C" ((BG "The agent surfaced 47 issues including a <b>security vulnerability</b>. Generating reports and analyzing dependencies is exactly agent work; but <b>judging correctness of security-relevant findings</b> and <b>approving commits</b> (the merge gate) require accountable human judgment.") + (WHY "<b>Validate assessment + approve commits</b>: the two human gates.") + (WN @("<b>B generating</b> the assessment is core agent work.", "<b>D reviewing plan dependencies</b> is delegable analysis.", "<b>E checking tasks.md exists</b> is a trivial filesystem check.")) + (SRC @(@($U_MODC,'App modernization: assessment, plan, tasks.md'),@($U_UPOV,'Copilot upgrade overview')))))
57 = "event: <b>pre-exec</b><br>config: <b>.copilot/hooks.yaml</b>" + (BG "This hook format (version/hooks/cli) guards generated shell commands: the script reads <b>$COPILOT_COMMAND</b> and exits nonzero to veto. Vetoing must happen <b>before execution</b>, and the CLI harness reads <b>.copilot/hooks.yaml</b>, never an Actions workflow path.") + (WHY "<b>pre-exec + .copilot/hooks.yaml</b>: validate before run, in the file the harness reads.") + (WN @("<b>post-exec</b> runs after the command: blocking there is too late.", "<b>.github/workflows/hooks.yaml</b> is a CI workflow path the CLI harness never reads.")) + (SRC @(@($U_CLI,'Copilot CLI')))
58 = (L "C" ((BG "<b>Autonomy levels</b> trade speed for control. Compliance-sensitive production deploys with secrets demand a human release gate: the agent may prepare everything, but only <b>required manual approvals</b> let it touch production.") + (WHY "<b>Human-in-the-loop + manual production approvals</b>: preparation automated, release human.") + (WN @("<b>A read-only</b> cannot deploy at all.", "<b>B non-prod-only</b> excludes the required production target.", "<b>D fully autonomous</b> with secrets and production access violates compliance.")) + (SRC @(@($U_CODAG,'Copilot coding agent')))))
}
